'use strict';
const ROOM_LIMITS={chess:[2,2],tictactoe:[2,2],connect:[2,2],mill:[2,2],ludo:[2,4],crazy8:[2,2],memory:[2,6],dice:[2,6],draw:[2,8],sound:[2,8]};
let currentRoom=null,roomToken='',roomTimer=null,roomBusy=false,roomSelected=null,roomPaint=false,roomDeferred=false,roomTone=0,roomAudio=null,shareOrigin=location.origin,roomGeneration=0,roomTab='game';
const roomDialog=document.createElement('dialog');roomDialog.id='room-dialog';roomDialog.className='play-dialog';roomDialog.innerHTML='<div class="dialog-header"><h2>Gemeinsam spielen</h2><button class="close" aria-label="Spielraum schließen">✕</button></div><div id="room-content"></div>';document.body.append(roomDialog);roomDialog.querySelector('.close').onclick=()=>roomDialog.close();
roomDialog.addEventListener('close',()=>{roomPaint=false;clearTimeout(roomTimer);roomGeneration++;if(roomAudio&&roomAudio.state!=='closed')roomAudio.close().catch(()=>{});roomAudio=null;roomTone=currentRoom?.state?.sequence||0;});
$('#network-open').onclick=()=>openNetwork();
async function roomAPI(path,{method='GET',body,token=roomToken}={}){
  const base=settings.server||location.origin;
  if(location.protocol==='https:'&&base.startsWith('http:'))throw Error('Diese Seite benötigt einen HTTPS-Spielraum-Server. Für LAN öffne die lokale Netzwerkadresse direkt.');
  let response;try{response=await fetch(base+path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(5000)});}catch{throw Error('Server nicht erreichbar. Öffne die LAN-Adresse oder prüfe den Spielraum-Server in den Einstellungen.');}
  let data;try{data=await response.json();}catch{throw Error('Hier läuft kein Spielraum-Server. Starte das lokale Projekt mit „npm start“ und öffne seine Netzwerkadresse.');}
  if(!response.ok){const error=Error(data.error||'Verbindung fehlgeschlagen.');error.status=response.status;throw error;}return data;
}
function saveSeat(id,token){try{sessionStorage.setItem('spielraum-seat-'+(settings.server||location.origin)+'-'+id,token)}catch{}}
function readSeat(id){try{return sessionStorage.getItem('spielraum-seat-'+(settings.server||location.origin)+'-'+id)||''}catch{return ''}}
function adoptRoom(data){if(currentRoom&&currentRoom.id===data.id&&data.version<currentRoom.version)return;const first=!currentRoom||currentRoom.id!==data.id;currentRoom=data;if(data.token){roomToken=data.token;saveSeat(data.id,data.token)}if(first){roomTab='game';roomSelected=null;roomTone=data.state?.sequence||0;}renderRoom();}
function openNetwork(game='tictactoe',joinOnly=false){if(currentRoom&&!joinOnly&&arguments.length===0){showDialog('#room-dialog');renderRoom();pollRoom();return;}clearTimeout(roomTimer);roomGeneration++;currentRoom=null;roomToken='';roomSelected=null;showDialog('#room-dialog');$('#room-content').innerHTML=`<p class="dialog-description">Ein Raum, mehrere Geräte. Alle benötigen denselben erreichbaren Spielraum-Server.</p><div class="detail-tabs" role="tablist"><button class="${joinOnly?'':'active'}" role="tab" aria-selected="${!joinOnly}" id="room-create-tab">Raum erstellen</button><button class="${joinOnly?'active':''}" role="tab" aria-selected="${joinOnly}" id="room-join-tab">Beitreten</button></div><div id="room-form"></div><button class="text-button" id="room-config">Server & Verbindung einstellen ↗</button>`;
  const form=create=>{$('#room-create-tab').classList.toggle('active',create);$('#room-join-tab').classList.toggle('active',!create);$('#room-create-tab').setAttribute('aria-selected',create);$('#room-join-tab').setAttribute('aria-selected',!create);$('#room-form').innerHTML=`<label class="field">Dein Name<input id="room-name" maxlength="24" value="${escapeHTML(settings.name)}"></label>${create?`<label class="field">Spiel<select id="room-game">${GAMES.filter(g=>NETWORK_IDS.has(g.id)).map(g=>`<option value="${g.id}">${escapeHTML(g.name)}</option>`).join('')}</select></label><label class="field">Personen<select id="room-seats"></select></label>`:'<label class="field">Raumcode<input id="room-code" maxlength="8" placeholder="z. B. A1B2C3D4" autocomplete="off"></label>'}<button class="primary full" id="room-submit">${create?'Raum erstellen':'Beitreten'} ⌘</button><p id="room-form-error" role="status"></p>`;
    if(create){$('#room-game').value=NETWORK_IDS.has(game)?game:'tictactoe';const options=()=>{const[min,max]=ROOM_LIMITS[$('#room-game').value];$('#room-seats').innerHTML=Array.from({length:max-min+1},(_,i)=>`<option value="${i+min}">${i+min} Personen</option>`).join('')};$('#room-game').onchange=options;options();}
    $('#room-submit').onclick=async()=>{const button=$('#room-submit'),error=$('#room-form-error');button.disabled=true;error.textContent='Verbindung wird hergestellt …';const name=$('#room-name').value.trim()||'Mitspieler';try{settings.name=name;applySettings();const health=await roomAPI('/api/health',{token:''});const base=settings.server||location.origin;const host=new URL(base).hostname;shareOrigin=['localhost','127.0.0.1','[::1]'].includes(host)?health.networkAddresses?.[0]||base:base;
      if(create){const data=await roomAPI('/api/rooms',{method:'POST',token:'',body:{game:$('#room-game').value,seats:+$('#room-seats').value,name,options:{pairs:settings.memoryPairs}}});adoptRoom(data);}
      else{const id=$('#room-code').value.trim().toUpperCase();if(!/^[A-F0-9]{8}$/.test(id))throw Error('Bitte den achtstelligen Raumcode eingeben.');roomToken=readSeat(id);let data=await roomAPI('/api/rooms/'+id,{token:roomToken});if(data.you<0)data=await roomAPI('/api/rooms/'+id+'/join',{method:'POST',token:'',body:{name}});adoptRoom(data);}
      pollRoom();
    }catch(e){error.textContent=e.message;button.disabled=false;}};
  };$('#room-create-tab').onclick=()=>form(true);$('#room-join-tab').onclick=()=>form(false);$('#room-config').onclick=()=>{roomDialog.close();openSettings('network')};form(!joinOnly);
}
async function pollRoom(){clearTimeout(roomTimer);if(!currentRoom||!roomDialog.open)return;const id=currentRoom.id,generation=roomGeneration;try{const data=await roomAPI('/api/rooms/'+id);if(generation!==roomGeneration||!roomDialog.open||currentRoom?.id!==id)return;const old=JSON.stringify(currentRoom);if(JSON.stringify(data)!==old)adoptRoom(data);const label=$('#room-connection');if(label)label.textContent='● Verbunden';}catch(e){if(generation!==roomGeneration)return;const label=$('#room-connection');if(label)label.textContent=e.message;}if(generation===roomGeneration&&roomDialog.open)roomTimer=setTimeout(pollRoom,800);}
async function roomAction(action){if(roomBusy||!currentRoom||!roomDialog.open)return;roomBusy=true;const id=currentRoom.id,generation=roomGeneration;try{let data;try{data=await roomAPI('/api/rooms/'+id+'/action',{method:'POST',body:{version:currentRoom.version,action}});}catch(e){if(e.status===409&&['stroke','tone'].includes(action.type)){const latest=await roomAPI('/api/rooms/'+id);currentRoom=latest;data=await roomAPI('/api/rooms/'+id+'/action',{method:'POST',body:{version:latest.version,action}});}else throw e;}if(generation===roomGeneration&&currentRoom?.id===id)adoptRoom(data);}catch(e){toast(e.message);if(generation===roomGeneration)await pollRoom();}finally{roomBusy=false;}}
function roomName(seat){return currentRoom?.players[seat]?.name||'Person '+(seat+1);}
function renderRoom(){if(!currentRoom)return;if(roomPaint){roomDeferred=true;return;}const r=currentRoom,s=r.state,g=GAMES.find(g=>g.id===r.game),mine=s&&s.turn===r.you,host=r.you===0;const invitation=shareOrigin+'/#room='+r.id;
  $('#room-content').innerHTML=`<div class="room-overview"><div><strong>${escapeHTML(g.name)}</strong><small id="room-connection">● Verbunden</small></div><b class="room-code">${r.id}</b></div><div class="room-members">${r.players.map((p,i)=>`<span class="room-member ${i===r.you?'me':''}"><i class="${p?.online?'online':''}"></i>${p?escapeHTML(p.name):'Freier Platz'}${i===0?' ♛':''}${i===r.you?' (du)':''}${host&&p&&i>0&&r.phase==='lobby'?`<button data-kick="${i}" aria-label="Platz ${i+1} freigeben">×</button>`:''}</span>`).join('')}</div><div class="detail-tabs" role="tablist"><button class="active" role="tab" aria-selected="true" data-roomtab="game">Spiel</button><button role="tab" aria-selected="false" data-roomtab="manual">Handbuch</button></div><div id="room-game-panel">${r.phase==='lobby'?`<p class="dialog-description">Teile den Einladungslink. Jede Person öffnet ihn auf ihrem eigenen Gerät und tritt mit ihrem Namen bei.</p><label class="field">Einladungslink<input readonly id="room-invite" value="${escapeHTML(invitation)}"></label><div class="game-controls"><button id="room-copy">Einladung kopieren</button>${host?`<button id="room-start" ${r.players.some(p=>!p)?'disabled':''}>Runde starten ▷</button>`:''}</div><p class="game-status">${r.players.some(p=>!p)?'Warte auf '+r.players.filter(p=>!p).length+' weitere Person(en).':host?'Alle sind da. Du kannst starten.':'Alle sind da. Die Gastgeberperson startet.'}</p>`:`<div class="game-status" id="room-turn">${s.winner!==null?s.winner==='draw'?'Unentschieden!':escapeHTML(roomName(s.winner))+' gewinnt!':['draw','sound'].includes(r.game)?'Alle können mitmachen':escapeHTML(roomName(s.turn))+(mine?' – du bist dran':' ist dran')}</div><div id="room-board"></div><div class="game-controls">${host?'<button id="room-restart">Neue Runde</button><button id="room-lobby">Zur Lobby</button>':''}</div>`}</div><div id="room-handbook" hidden>${handbookHTML(g)}</div><div class="game-controls"><button id="room-leave">Raumansicht verlassen</button></div><p class="game-instruction">Dein Platz bleibt für eine Rückkehr in diesem Browser reserviert. In der Lobby kann die Gastgeberperson Plätze freigeben. Räume sind nicht dauerhaft gespeichert.</p>`;
  rootRoomTabs();if(roomTab==='manual'){$('#room-game-panel').hidden=true;$('#room-handbook').hidden=false;roomDialog.querySelectorAll('[data-roomtab]').forEach(b=>{const on=b.dataset.roomtab==='manual';b.classList.toggle('active',on);b.setAttribute('aria-selected',on)})}
  if($('#room-copy'))$('#room-copy').onclick=async()=>{try{await navigator.clipboard.writeText(invitation);toast('Einladungslink kopiert')}catch{$('#room-invite').select();toast('Link markieren und kopieren.')}};
  if($('#room-start'))$('#room-start').onclick=()=>roomAction({type:'start'});
  if($('#room-restart'))$('#room-restart').onclick=()=>roomAction({type:'restart'});
  if($('#room-lobby'))$('#room-lobby').onclick=()=>roomAction({type:'lobby'});
  document.querySelectorAll('[data-kick]').forEach(b=>b.onclick=()=>roomAction({type:'kick',seat:+b.dataset.kick}));
  $('#room-leave').onclick=()=>{roomDialog.close();currentRoom=null;roomToken='';roomSelected=null;};
  if(r.phase==='playing')renderRoomGame(s,mine);
}
function rootRoomTabs(){roomDialog.querySelectorAll('[data-roomtab]').forEach(b=>b.onclick=()=>{roomTab=b.dataset.roomtab;const manual=roomTab==='manual';$('#room-game-panel').hidden=manual;$('#room-handbook').hidden=!manual;roomDialog.querySelectorAll('[data-roomtab]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-selected',on)})});}
function renderRoomGame(s,mine){const root=$('#room-board'),r=currentRoom,enabled=mine&&s.winner===null,emojis=['🌿','🍄','🌻','🍋','🐸','🦋','🍒','🐝','🐬','🦊','🌙','🍉','🐳','🌈','🌸','🐧','🍇','⭐','🍓','🦉','🐢','🌵','🦄','🎈'];
  if(s.game==='chess'){window.drawChessBoard(root,window.makeRoomChess(s.history),enabled,a=>roomAction(a));}
  if(s.game==='tictactoe'){root.innerHTML=`<div class="board board-ttt">${s.board.map((v,i)=>`<button class="cell" data-place="${i}" aria-label="Feld ${i+1}: ${v===null?'leer':v===0?'X':'O'}" ${enabled&&v===null?'':'disabled'}>${v===null?'':v===0?'X':'O'}</button>`).join('')}</div>`;root.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>roomAction({type:'place',index:+b.dataset.place}));}
  if(s.game==='connect'){root.innerHTML=`<div class="board board-connect">${s.board.map((v,i)=>`<button class="cell ${v===null?'':'p'+(v+1)}" data-column="${i%7}" aria-label="Reihe ${Math.floor(i/7)+1}, Spalte ${i%7+1}: ${v===null?'leer':roomName(v)}" ${enabled?'':'disabled'}></button>`).join('')}</div>`;root.querySelectorAll('[data-column]').forEach(b=>b.onclick=()=>roomAction({type:'drop',column:+b.dataset.column}));}
  if(s.game==='memory'){root.innerHTML=`<p class="game-instruction">${r.players.map((p,i)=>escapeHTML(p.name)+': '+s.points[i]+' Paare').join(' · ')} · ${s.moves} Züge</p><div class="board board-memory extended-memory" style="--memory-cols:${s.pairs<=8?4:s.pairs<=16?6:8}">${s.board.map((v,i)=>`<button class="cell ${s.matched.includes(i)?'matched':''}" data-flip="${i}" aria-label="Karte ${i+1}: ${v===null?'verdeckt':emojis[v]}" ${enabled&&!s.flipAt&&v===null?'':'disabled'}>${v===null?'✦':emojis[v]}</button>`).join('')}</div>`;root.querySelectorAll('[data-flip]').forEach(b=>b.onclick=()=>roomAction({type:'flip',index:+b.dataset.flip}));}
  if(s.game==='mill'){root.innerHTML=`<p class="game-instruction">${s.capture?'Wähle einen gegnerischen Stein zum Entfernen.':s.placed[s.turn]<9?'Noch '+(9-s.placed[s.turn])+' Steine setzen.':roomSelected===null?'Wähle deinen Stein.':'Wähle das Zielfeld.'}</p><div class="mill-board"><svg viewBox="0 0 600 600" aria-hidden="true"><g fill="none" stroke="#a4b294" stroke-width="3"><rect x="35" y="35" width="530" height="530"/><rect x="123" y="123" width="354" height="354"/><rect x="211" y="211" width="178" height="178"/><path d="M300 35V211M300 389V565M35 300H211M389 300H565"/></g></svg>${MILL_POINTS.map(([x,y],i)=>`<button class="mill-point ${s.board[i]===null?'':'p'+(s.board[i]+1)} ${roomSelected===i?'selected':''}" style="left:${(35+x*88.333)/6}%;top:${(35+y*88.333)/6}%" data-mill="${i}" aria-label="Position ${i+1}: ${s.board[i]===null?'leer':escapeHTML(roomName(s.board[i]))}" ${enabled?'':'disabled'}></button>`).join('')}</div>`;root.querySelectorAll('[data-mill]').forEach(b=>b.onclick=()=>{const i=+b.dataset.mill;if(s.capture){roomSelected=null;roomAction({type:'capture',index:i})}else if(s.placed[r.you]<9){roomAction({type:'move',from:null,to:i})}else if(s.board[i]===r.you){roomSelected=i;renderRoom()}else if(roomSelected!==null){const from=roomSelected;roomSelected=null;roomAction({type:'move',from,to:i})}});}
  if(s.game==='ludo'){let html='';LUDO_PATH.forEach(([row,col],i)=>html+=`<span class="ludo-field ${i%10===0?'color-'+Math.floor(i/10):''}" style="grid-row:${row+1};grid-column:${col+1}"></span>`);s.pieces.forEach((pieces,p)=>{const color=s.colors[p];for(const[row,col]of [...LUDO_HOMES[color],...LUDO_GOALS[color]])html+=`<span class="ludo-field color-${color} goal" style="grid-row:${row+1};grid-column:${col+1}"></span>`;pieces.forEach((n,i)=>{const[row,col]=n<0?LUDO_HOMES[color][i]:n>=40?LUDO_GOALS[color][n-40]:LUDO_PATH[(n+color*10)%40];const ok=enabled&&p===r.you&&s.waiting;html+=`<button class="ludo-piece color-${color} ${ok?'movable':''}" style="grid-row:${row+1};grid-column:${col+1}" data-piece="${i}" aria-label="${escapeHTML(roomName(p))} Figur ${i+1}" ${ok?'':'disabled'}>${i+1}</button>`})});root.innerHTML=`<p class="game-instruction">${escapeHTML(s.message)}</p><div class="ludo-board">${html}</div><div class="game-controls"><button id="network-roll" ${enabled&&!s.waiting?'':'disabled'}>Würfeln ⚄</button></div>`;$('#network-roll').onclick=()=>roomAction({type:'roll'});root.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>roomAction({type:'move',piece:+b.dataset.piece}));}
  if(s.game==='crazy8'){const card=(c,attrs)=>`<button class="playing-card ${['♥','♦'].includes(c.suit)?'red':''}" ${attrs}><small>${c.rank}${c.suit}</small><strong>${c.suit}</strong><small>${c.rank}${c.suit}</small></button>`;root.innerHTML=`<div class="cards-table"><span>${s.counts[1-r.you]} gegnerische Karten</span>${card(s.top,'disabled aria-label="Ablage: '+s.top.rank+' '+s.top.suit+'"')}<span>Farbe: ${s.suit}<br>${s.deckCount} im Stapel</span></div><div class="cards-hand">${s.hand.map((c,i)=>card(c,`data-card="${i}" aria-label="${c.rank} ${c.suit}" ${enabled&&!s.wish&&(c.rank==='8'||c.suit===s.suit||c.rank===s.top.rank)?'':'disabled'}`)).join('')}</div><div class="game-controls">${s.wish&&enabled?['♠','♥','♦','♣'].map(suit=>`<button data-wish="${suit}" aria-label="Wunschfarbe ${suit}">${suit}</button>`).join(''):`<button id="network-draw-card" ${enabled&&!s.wish?'':'disabled'}>Karte ziehen</button>`}</div>`;root.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>roomAction({type:'card',index:+b.dataset.card}));root.querySelectorAll('[data-wish]').forEach(b=>b.onclick=()=>roomAction({type:'wish',suit:b.dataset.wish}));if($('#network-draw-card'))$('#network-draw-card').onclick=()=>roomAction({type:'draw'});}
  if(s.game==='dice'){root.innerHTML=`<p class="game-instruction">Runde ${s.round} · Wurf ${s.rolls}/3 · Summe ${s.dice.reduce((a,b)=>a+b,0)}</p><div class="dice-row">${s.dice.map((v,i)=>`<button class="${s.held.includes(i)?'held':''}" data-hold="${i}" aria-label="Würfel ${i+1}: ${v}" ${enabled&&s.rolls?'':'disabled'}>${['⚀','⚁','⚂','⚃','⚄','⚅'][v-1]}</button>`).join('')}</div><div class="game-controls"><button id="network-dice-roll" ${enabled&&s.rolls<3?'':'disabled'}>Würfeln</button><button id="network-dice-next" ${enabled&&s.rolls?'':'disabled'}>Nächste Person</button></div>`;root.querySelectorAll('[data-hold]').forEach(b=>b.onclick=()=>roomAction({type:'hold',index:+b.dataset.hold}));$('#network-dice-roll').onclick=()=>roomAction({type:'roll'});$('#network-dice-next').onclick=()=>roomAction({type:'next'});}
  if(s.game==='draw')renderRoomDrawing(root,s);
  if(s.game==='sound'){root.innerHTML='<p class="game-instruction">Aktiviere den Ton auf deinem Gerät. Gemeinsam erzeugte Töne werden mit kurzer Verzögerung übertragen.</p><div class="game-controls"><button id="network-audio">Ton auf meinem Gerät aktivieren</button></div><div class="sound-pads">'+['A','S','D','F','G','H','J','K'].map((k,i)=>`<button data-tone="${i}" aria-label="Ton ${i+1}">${k}</button>`).join('')+'</div>';$('#network-audio').onclick=async()=>{roomAudio??=new (window.AudioContext||window.webkitAudioContext)();await roomAudio.resume();toast('Ton auf diesem Gerät aktiviert')};root.querySelectorAll('[data-tone]').forEach(b=>b.onclick=async()=>{roomAudio??=new (window.AudioContext||window.webkitAudioContext)();await roomAudio.resume();roomAction({type:'tone',note:+b.dataset.tone})});for(const tone of s.tones)if(tone.id>roomTone){networkTone(tone.note);roomTone=tone.id;}}
}
function networkTone(note){if(!settings.sound||settings.volume===0||!roomAudio||roomAudio.state!=='running')return;const osc=roomAudio.createOscillator(),gain=roomAudio.createGain(),t=roomAudio.currentTime;osc.frequency.value=[261.63,293.66,329.63,349.23,392,440,493.88,523.25][note];gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(settings.volume/100*.3,t+.015);gain.gain.exponentialRampToValueAtTime(.001,t+.7);osc.connect(gain);gain.connect(roomAudio.destination);osc.start();osc.stop(t+.75);}
let drawingColor='#477258',drawingWidth=5;
function renderRoomDrawing(root,s){root.innerHTML=`<div class="draw-tools"><label>Farbe <input id="room-color" type="color" value="${drawingColor}"></label><label>Pinsel <input id="room-width" type="range" min="1" max="32" value="${drawingWidth}"></label></div><canvas class="draw-canvas" id="room-canvas" width="1000" height="650" aria-label="Gemeinsame Zeichenfläche"></canvas><div class="game-controls"><button id="room-export">Bild herunterladen ↓</button>${currentRoom.you===0?'<button id="room-clear">Fläche leeren</button>':''}</div>`;$('#room-color').oninput=e=>drawingColor=e.target.value;$('#room-width').oninput=e=>drawingWidth=+e.target.value;const canvas=$('#room-canvas'),ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,1000,650);ctx.lineCap='round';ctx.lineJoin='round';const paint=stroke=>{ctx.strokeStyle=stroke.color;ctx.lineWidth=stroke.width;ctx.beginPath();stroke.points.forEach(([x,y],i)=>i?ctx.lineTo(x*1000,y*650):ctx.moveTo(x*1000,y*650));if(stroke.points.length===1){const[x,y]=stroke.points[0];ctx.lineTo(x*1000+.1,y*650+.1)}ctx.stroke()};s.strokes.forEach(paint);let points=[];const point=e=>{const rect=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height))]};canvas.onpointerdown=e=>{if(roomBusy)return;roomPaint=true;canvas.setPointerCapture(e.pointerId);points=[point(e)];};canvas.onpointermove=e=>{if(!roomPaint||points.length>=200)return;points.push(point(e));paint({points:points.slice(-2),color:drawingColor,width:drawingWidth})};const finish=()=>{if(!roomPaint)return;roomPaint=false;const stroke={type:'stroke',points:points.slice(),color:drawingColor,width:drawingWidth};points=[];roomAction(stroke);if(roomDeferred){roomDeferred=false;renderRoom()}};canvas.onpointerup=finish;canvas.onpointercancel=finish;if($('#room-clear'))$('#room-clear').onclick=()=>roomAction({type:'clear'});$('#room-export').onclick=()=>{const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='spielraum-gemeinsam.png';a.click()};}
const invited=location.hash.match(/^#room=([A-Fa-f0-9]{8})$/);if(invited){openNetwork('tictactoe',true);$('#room-code').value=invited[1].toUpperCase();}
